/**
 * Test-only transcription of the two-page State Bank of Sikkim Pay Matrix,
 * Annexure-I. Values are copied from the PDF's selectable text layer.
 *
 * Source: https://www.statebankofsikkim.com/SBSPAYMATRIX.pdf
 * Page 1 lists Levels 4, 5, 6, 7, 9, 10, 11 and 12.
 * Page 2 lists Levels 14, 15, 16, 17, 19, 20, 21 and 22.
 *
 * Rows are pay-cell numbers in ascending order. Trailing blank cells are
 * omitted; no missing value is padded or inferred. This fixture is for
 * verification tests only and is not used by the salary calculator.
 */

function parseRows(source) {
  return source.trim().split("\n").map((line) => line.trim().split(/\s+/).map(Number));
}

